import {blendSequenceNumber} from './sequence-blending.js';
import {validComponents} from './scene-components.js';
import {Quaternion,Vector3,Matrix4} from 'three';
const finite=v=>Number.isFinite(v)&&Math.abs(v)<=1e6;
const vector=(v,n)=>Array.isArray(v)&&v.length===n&&v.every(finite);
export const validSequencePoseWeight=track=>track.poseWeight===undefined||track.type==='skeletalPose'&&Number.isFinite(track.poseWeight)&&track.poseWeight>=0&&track.poseWeight<=1;
export function validRecordedState(type,track,value){
  if(type==='componentState')return typeof track.component==='string'&&track.component.length>0&&(value===null||value?.id===track.component&&value.type!=='Transform'&&validComponents([value]))&&JSON.stringify(value).length<=65536;
  return type==='skeletalPose'&&Array.isArray(value)&&value.length<=2048&&new Set(value.map(b=>b?.bone)).size===value.length&&value.every(b=>typeof b?.bone==='string'&&b.bone.length>0&&b.bone.length<=160&&vector(b.position,3)&&vector(b.scale,3)&&b.scale.every(v=>v>0)&&vector(b.quaternion,4)&&Math.abs(Math.hypot(...b.quaternion)-1)<.001);
}
export function validateSkeletalBoneName(name){if(typeof name!=='string'||!name||name.length>160)throw Error('골격에는 160자 이하의 고유한 뼈 이름이 필요해요.');}
export function traverseSkeletalBones(group,visit){if(!group?.isObject3D){group?.traverse?.(b=>{if(b.isBone)visit(b);});return;}const owner=group.userData.objectId,stack=[group];while(stack.length){const node=stack.pop();if(node!==group&&owner&&node.userData?.objectId&&node.userData.objectId!==owner)continue;if(node.isBone)visit(node);for(let i=node.children.length-1;i>=0;i--)stack.push(node.children[i]);}}
export function skeletalBoneIndex(group){const bones=new Map();traverseSkeletalBones(group,b=>{validateSkeletalBoneName(b.name);if(bones.has(b.name))throw Error('중복 뼈 이름은 재생·조회할 수 없어요. 고유한 이름을 지정하세요.');bones.set(b.name,b);});return bones;}
const boneRow=b=>({bone:b.name,position:b.position.toArray(),quaternion:b.quaternion.toArray(),scale:b.scale.toArray()});
export function captureSkeletalPose(group){return [...skeletalBoneIndex(group).values()].map(boneRow);}
export function captureSkeletalPosePage(group,{offset=0,limit=64,boneNames=[],space='local'}={}){
  if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>512||!['local','world'].includes(space)||!Array.isArray(boneNames)||boneNames.length>2048||new Set(boneNames).size!==boneNames.length||boneNames.some(n=>typeof n!=='string'||!n||n.length>160))throw Error('골격 조회 페이지·뼈 필터·좌표계를 확인하세요.');
  const index=skeletalBoneIndex(group);for(const name of boneNames)if(!index.has(name))throw Error('조회할 뼈가 대상에 없어요: '+name);const selected=boneNames.length?new Set(boneNames):null,rows=[];let total=0;for(const [name,b]of index)if(!selected||selected.has(name)){if(total>=offset&&total-offset<limit)rows.push(b);total++;}
  let bones;if(space==='local')bones=rows.map(boneRow);else{const visited=new Set(),ordered=[];for(const bone of rows){const path=[];for(let node=bone;node&&!visited.has(node);node=node.parent){visited.add(node);path.push(node);}ordered.push(...path.reverse());}for(const node of ordered)node.updateWorldMatrix(false,false);const p=new Vector3(),q=new Quaternion(),s=new Vector3(),reconstructed=new Matrix4();bones=rows.map(b=>{const matrix=b.matrixWorld;if(matrix.elements.some(v=>!Number.isFinite(v)))throw Error('골격 월드 행렬 값을 확인하세요.');matrix.decompose(p,q,s);q.normalize();if([...p.toArray(),...q.toArray(),...s.toArray()].some(v=>!Number.isFinite(v)))throw Error('특이 월드 행렬은 골격 TRS로 조회할 수 없어요.');reconstructed.compose(p,q,s);const trsExact=matrix.elements.every((v,i)=>Math.abs(v-reconstructed.elements[i])<=1e-8*Math.max(1,Math.abs(v)));return {bone:b.name,position:p.toArray(),quaternion:q.toArray(),scale:s.toArray(),matrix:matrix.toArray(),trsExact};});}
  return {total,modelTotal:index.size,space,offset,bones,nextOffset:offset+limit<total?offset+limit:null};
}
export function applySkeletalPose(group,pose){if(!validRecordedState('skeletalPose',{},pose))throw Error('녹화 골격 포즈 형식 오류');const bones=skeletalBoneIndex(group);if(pose.some(p=>!bones.has(p.bone)))throw Error('녹화한 뼈가 대상에 없어요.');for(const p of pose){const bone=bones.get(p.bone);bone.position.fromArray(p.position);bone.quaternion.fromArray(p.quaternion).normalize();bone.scale.fromArray(p.scale);}group?.updateWorldMatrix(true,true);}
export function applyComponentStates(object,changes){const next=[...(object.components||[])];for(const {track,value} of changes){if(!validRecordedState('componentState',track,value))throw Error('녹화 컴포넌트 형식 오류');if(value===null){const i=next.findIndex(c=>c.id===track.component);if(i>=0)next.splice(i,1);}}for(const {track,value,index} of changes){if(value===null)continue;const i=next.findIndex(c=>c.id===track.component);if(i<0)next.splice(index===undefined?next.length:Math.min(index,next.length),0,structuredClone(value));else next[i]=structuredClone(value);}if(!validComponents(next))throw Error('녹화 컴포넌트 조합을 확인하세요.');object.components=next;}
export function applyComponentState(object,track,value){applyComponentStates(object,[{track,value}]);}

const samePoseLayout=(a,b)=>a.length===b.length&&a.every((bone,i)=>bone.bone===b[i].bone);
export class SkeletalPoseProgram{
  constructor(keys){this.keys=[...keys].sort((a,b)=>a.time-b.time);if(!this.keys.length||this.keys.some(k=>!Number.isFinite(k.time)||!validRecordedState('skeletalPose',{},k.value)))throw Error('골격 트랙 포즈를 확인하세요.');const layouts=new Map();this.poseRows=0;this.layouts=this.keys.map(k=>{this.poseRows+=k.value.length;const names=k.value.map(b=>b.bone),signature=JSON.stringify(names);let layout=layouts.get(signature);if(!layout){layout={names};layouts.set(signature,layout);}return layout;});this.layoutCount=layouts.size;}
  upperBound(time){let lo=0,hi=this.keys.length;while(lo<hi){const m=(lo+hi)>>1;if(this.keys[m].time<=time)lo=m+1;else hi=m;}return lo;}
}
export class SkeletalPoseTrack{
  constructor(group,keys,{time}={}){this.group=group;this.program=keys instanceof SkeletalPoseProgram?keys:new SkeletalPoseProgram(keys);this.keys=this.program.keys;this.layouts=this.program.layouts;this.q=new Quaternion();this.targetQ=new Quaternion();this.bind(Math.max(0,this.program.upperBound(time??this.keys[0].time)-1));}
  rebind(time){this.signature=undefined;this.prepare(time);}
  bind(index){const signature=this.layouts[index];if(signature===this.signature)return;const bones=skeletalBoneIndex(this.group),bound=signature.names.map(name=>{const bone=bones.get(name);if(!bone)throw Error('녹화 뼈가 대상에 없어요: '+name);return bone;});const edges=new Map();for(const bone of bound)for(let node=bone;node&&node!==this.group;node=node.parent){if(edges.has(node))break;edges.set(node,[node.parent,node.userData?.objectId]);}this.edges=[...edges];this.owner=this.group?.userData?.objectId;this.bones=bound;this.signature=signature;}
  prepare(time){if(!Number.isFinite(time))throw Error('골격 시간 값을 확인하세요.');const lo=this.preparedTime===time?this.preparedUpper:this.program.upperBound(time);this.bind(Math.max(0,lo-1));this.preparedTime=time;this.preparedUpper=lo;return lo;}
  validateBinding(time){this.prepare(time);if(this.owner!==this.group?.userData?.objectId||this.edges.some(([node,[parent,owner]])=>node.parent!==parent||node.userData?.objectId!==owner)||this.bones.some((bone,i)=>bone.name!==this.signature.names[i])){this.signature=undefined;this.prepare(time);}}
  sampleBone(time,name,{weight=1,basis,bone}={}){if(!Number.isFinite(time)||!Number.isFinite(weight)||weight<0||weight>1)throw Error('골격 혼합 시간·가중치를 확인하세요.');const lo=this.program.upperBound(time),first=Math.max(0,lo-1),layout=this.layouts[first];layout.indices??=new Map(layout.names.map((name,i)=>[name,i]));const i=layout.indices.get(name);if(i===undefined)throw Error('녹화 뼈가 대상에 없어요: '+name);if(!bone){this.validateBinding(time);bone=this.bones[i];}const last=Math.min(lo,this.keys.length-1),a=this.keys[first],b=this.keys[last],alpha=a===b||a.interpolation==='step'||this.layouts[first]!==this.layouts[last]?0:Math.max(0,Math.min(1,(time-a.time)/(b.time-a.time))),x=a.value[i],y=alpha?b.value[i]:x,base=weight<1?basis?.(bone):null,position=[],scale=[];for(let k=0;k<3;k++){const p=blendSequenceNumber(x.position[k],y.position[k],alpha),s=blendSequenceNumber(x.scale[k],y.scale[k],alpha);position[k]=base?blendSequenceNumber(base.position[k],p,weight):p;scale[k]=base?blendSequenceNumber(base.scale[k],s,weight):s;}this.q.fromArray(x.quaternion).slerp(this.targetQ.fromArray(y.quaternion),alpha).normalize();if(base)this.q.copy(this.targetQ.fromArray(base.quaternion).slerp(this.q,weight).normalize());return {bone,position,scale,quaternion:this.q.toArray()};}
  sample(time,{updateMatrices=true,boneNames,weight=1,basis,validated=false}={}){if(!Number.isFinite(weight)||weight<0||weight>1)throw Error('골격 포즈 가중치를 확인하세요.');if(!validated)this.validateBinding(time);const lo=this.preparedUpper,first=Math.max(0,lo-1),last=Math.min(lo,this.keys.length-1),a=this.keys[first],b=this.keys[last],alpha=a===b||a.interpolation==='step'||this.layouts[first]!==this.layouts[last]?0:Math.max(0,Math.min(1,(time-a.time)/(b.time-a.time)));for(let i=0;i<this.bones.length;i++){const bone=this.bones[i];if(boneNames&&!boneNames.has(this.signature.names[i]))continue;const x=a.value[i],y=alpha?b.value[i]:x,base=weight<1?basis?.(bone):null;for(let k=0;k<3;k++){const p=x.position[k]+(y.position[k]-x.position[k])*alpha,s=x.scale[k]+(y.scale[k]-x.scale[k])*alpha;bone.position.setComponent(k,base?base.position[k]+(p-base.position[k])*weight:p);bone.scale.setComponent(k,base?base.scale[k]+(s-base.scale[k])*weight:s);}this.q.fromArray(x.quaternion).slerp(this.targetQ.fromArray((alpha?y:x).quaternion),alpha).normalize();if(base)bone.quaternion.fromArray(base.quaternion).slerp(this.q,weight).normalize();else bone.quaternion.copy(this.q);}if(updateMatrices)this.group?.updateWorldMatrix(true,true);}
}

function reduceFixedSkeletalKeys(keys,tolerance){if(!Number.isFinite(tolerance)||tolerance<0)throw Error('키 오차 범위 오류');if(keys.length<3)return keys;const keep=new Set([0,keys.length-1]),pending=[[0,keys.length-1]],aQ=new Quaternion(),bQ=new Quaternion(),actual=new Quaternion();while(pending.length){const [first,last]=pending.pop();if(last-first<2)continue;let best=-1,error=tolerance;const a=keys[first],b=keys[last];for(let i=first+1;i<last;i++){const t=(keys[i].time-a.time)/(b.time-a.time);let distance=0;for(let j=0;j<a.value.length;j++){const x=a.value[j],y=b.value[j],v=keys[i].value[j];if(!v||x.bone!==v.bone||y.bone!==v.bone)throw Error('녹화 중 골격 구성이 바뀌었어요.');for(const field of ['position','scale'])for(let k=0;k<3;k++)distance=Math.max(distance,Math.abs(v[field][k]-(x[field][k]+(y[field][k]-x[field][k])*t)));distance=Math.max(distance,aQ.fromArray(x.quaternion).slerp(bQ.fromArray(y.quaternion),t).angleTo(actual.fromArray(v.quaternion)));}if(distance>error){error=distance;best=i;}}if(best>=0){keep.add(best);pending.push([first,best],[best,last]);}}return [...keep].sort((a,b)=>a-b).map(i=>keys[i]);}

export function reduceSkeletalKeys(keys,tolerance){if(!Number.isFinite(tolerance)||tolerance<0)throw Error('키 오차 범위 오류');const out=[];let start=0;for(let i=1;i<=keys.length;i++)if(i===keys.length||!samePoseLayout(keys[i-1].value,keys[i].value)){out.push(...reduceFixedSkeletalKeys(keys.slice(start,i),tolerance));start=i;}return out;}
